382	void __unw_add_dynamic_eh_frame_section(unw_word_t eh_frame_start) {
383	  // The eh_frame section start serves as the mh_group
384	  unw_word_t mh_group = eh_frame_start;
385	  CFI_Parser<LocalAddressSpace>::CIE_Info cieInfo;
386	  CFI_Parser<LocalAddressSpace>::FDE_Info fdeInfo;
387	  auto p = (LocalAddressSpace::pint_t)eh_frame_start;
388	  while (LocalAddressSpace::sThisAddressSpace.get32(p)) {
389	    if (CFI_Parser<LocalAddressSpace>::decodeFDE(
390	            LocalAddressSpace::sThisAddressSpace, p, &fdeInfo, &cieInfo,
391	            true) == NULL) {
392	      DwarfFDECache<LocalAddressSpace>::add((LocalAddressSpace::pint_t)mh_group,
393	                                            fdeInfo.pcStart, fdeInfo.pcEnd,
394	                                            fdeInfo.fdeStart);
395	      p += fdeInfo.fdeLength;
396	    } else if (CFI_Parser<LocalAddressSpace>::parseCIE(
397	                   LocalAddressSpace::sThisAddressSpace, p, &cieInfo) == NULL) {
398	      p += cieInfo.cieLength;
399	    } else
400	      return;
401	  }
402	}
