128	  static void removeAllIn(pint_t mh);
129	  static void iterateCacheEntries(void (*func)(unw_word_t ip_start,
130	                                               unw_word_t ip_end,
131	                                               unw_word_t fde, unw_word_t mh));
132	
133	private:
